module top_module(Q,
    E,
    D,
    CLK,
    AR,
    ADDR);output [31:0] Q;
  input E;
  input [31:0] D;
  input CLK;
  input AR;
  input [4:0] ADDR;

  reg [31:0] registers [0:29]; // Corrected register declaration

  assign Q = registers[ADDR];

  always @(posedge CLK or posedge AR) begin
    if (AR) begin
      // Reset all registers when AR is high
      integer i;
      for (i = 0; i < 30; i = i + 1) begin
        registers[i] <= 32'b0;
      end
    end else if (E) begin
      // Write to the register if E is high
      registers[ADDR] <= D;
    end
  end
endmodule

