module shift_register_64bit (
    input wire clk,
    input wire rst,
    input wire d,
    output reg [63:0] q
);

    wire [15:0] q1, q2, q3, q4;

    shift_register_16bit sr1 (
        .clk(clk),
        .rst(rst),
        .d(d),
        .q(q1)
    );

    shift_register_16bit sr2 (
        .clk(clk),
        .rst(rst),
        .d(d),
        .q(q2)
    );

    shift_register_16bit sr3 (
        .clk(clk),
        .rst(rst),
        .d(d),
        .q(q3)
    );

    shift_register_16bit sr4 (
        .clk(clk),
        .rst(rst),
        .d(d),
        .q(q4)
    );

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q <= 64'b0;
        end else begin
            q <= {q1, q2, q3, q4};
        end
    end

endmodule

module shift_register_16bit (
    input wire clk,
    input wire rst,
    input wire d,
    output reg [15:0] q
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q <= 16'b0;
        end else begin
            q <= {q[14:0], d};
        end
    end

endmodule

